"""Actual local and disconnected capabilities; configured is not connected."""
from __future__ import annotations

import os


def provider_statuses() -> list[dict]:
    from .copilot import provider_status
    from .data import historical_source_status
    ai = provider_status()
    historical = historical_source_status()
    return [
        {"id": "historical_data", "name": "Optional verified local archives", "status": historical["status"], "configured": historical["configured"], "manifest_installed": historical["manifest_installed"], "capabilities": ["synthetic_demo", "strict_utc_coarsening"] + (["optional_historical_backtest"] if historical["manifest_installed"] else []), "message": historical["message"]},
        {"id": "analysis", "name": "Offline research analyst", "status": "offline_rules", "configured": True, "capabilities": ["deterministic_explanation"], "message": "Explanations are generated by transparent local rules, not an external language model."},
        {"id": "ai", "name": "Strategy copilot", "status": ai["status"], "configured": bool(os.environ.get("KEDR_AI_API_KEY")), "adapter_ready": ai["configured"], "capabilities": ["structured_proposals", "explicit_approval", "saved_evidence"] if ai["configured"] else [], "message": ai["setup"]},
        {"id": "news", "name": "News and sentiment", "status": "demo_fixture", "configured": bool(os.environ.get("KEDR_NEWS_API_KEY")), "capabilities": ["labelled_fixture"], "message": "Static demonstration articles, not current news. No live sentiment feed is connected."},
        {"id": "ml", "name": "Bounded local ML worker", "status": "local_bounded_worker", "configured": True, "capabilities": ["save_research_draft", "logistic_direction", "ridge_return", "chronological_splits", "native_model_registry"], "message": "A separate limited process fits fixed small models on authorized historical data. Historical evaluation is retrospective; prediction nodes remain disconnected."},
        {"id": "execution", "name": "Exchange execution", "status": "preview_only", "configured": False, "capabilities": [], "message": "No exchange account, order routing, paper fills or live bot worker is connected."},
    ]


def news_fixture(symbol: str, locale: str = "ru") -> dict:
    ru = locale != "en"
    return {
        "mode": "demo_fixture",
        "is_current": False,
        "symbol": symbol,
        "provider_status": next(p for p in provider_statuses() if p["id"] == "news"),
        "articles": [
            {"id": "fixture-methodology", "title": "Демо: почему время публикации важно" if ru else "Demo: why publication time matters", "summary": "Учебная запись, а не новость. Исторический текст нельзя использовать в сигнале раньше его первого наблюдения." if ru else "An educational fixture, not news. Historical text must not enter a signal before it was first observed.", "sentiment": "neutral", "published_at": "2025-01-01T09:00:00Z", "first_seen_at": "2025-01-01T09:05:00Z", "symbol": symbol, "is_fixture": True},
            {"id": "fixture-risk", "title": "Демо: настроение и будущая доходность" if ru else "Demo: sentiment and future returns", "summary": "Учебная запись. Положительная тональность текста сама по себе не доказывает преимущество торговой стратегии." if ru else "An educational fixture. Positive text sentiment alone does not establish a trading advantage.", "sentiment": "positive", "published_at": "2025-01-02T10:00:00Z", "first_seen_at": "2025-01-02T10:03:00Z", "symbol": symbol, "is_fixture": True},
        ],
    }
